  if(S.units['p'+c.page+'c'+c.col]===false)continue;
  rows(k).forEach((r,i)=>{if(r.cat==='PCC'&&r.a==='N')current[k+'#'+i]=PCCFinal.statement(c,r,i,unitName(c.page,c.col),NAMES[c.proc]||PAGES[c.page]);});
