document.getElementById('paper-page').onchange=e=>{paperPage=Number(e.target.value);showPaper();};document.getElementById('paper-prev').onclick=()=>{paperPage--;showPaper();};document.getElementById('paper-next').onclick=()=>{paperPage++;showPaper();};document.getElementById('paper-zoom').onchange=sizePaper;window.addEventListener('resize',sizePaper);document.getElementById('paper-print').onclick=printPaper;document.getElementById('paper-export').onclick=exportPaper;document.getElementById('paper-new').onclick=()=>{if(confirm('Limpar o preenchimento? Salve seu JSON antes.')){localStorage.removeItem(KEY);location.reload();}};
document.getElementById('back').onclick=()=>document.getElementById('phrases').close();document.getElementById('phrases').onclose=()=>{if(editing){let c=CFG.itens[editing];if(rows(editing).some(r=>r.a))S.units['p'+c.page+'c'+c.col]=true;}editing=null;save();refreshPaper();};document.getElementById('paper-note-save').onclick=()=>{if(paperNotePage==='final'){S.fields.consideracoes_finais=document.getElementById('paper-note-text').value;delete S.fields.consideracoes_finais_col2;}else if(paperNotePage===14){S.fields.obs_gerais_continuacao=document.getElementById('paper-note-text').value;delete S.fields.obs_gerais_continuacao_col2;}else S.notes[paperNotePage]=document.getElementById('paper-note-text').value;save();document.getElementById('paper-note').close();refreshPaper();};
document.getElementById('paper-import').onchange=async e=>{try{let s=migrateCurrentState(JSON.parse(await e.target.files[0].text()));if(s.schema!=='appcc-bpf-1'||!s.a||!s.meta)throw Error('Arquivo incompatível.');for(let [k,rs] of Object.entries(s.a)){if(!CFG.itens[k])throw Error('Item inválido');for(let [i,r] of Object.entries(rs)){if(!CFG.itens[k].frases[i]||(r.a&&!['S','N','A'].includes(r.a))||(r.cat&&!CATS.includes(r.cat))||(r.a==='A'&&!CFG.itens[k].allowNA)||r.P!==undefined)throw Error('Resposta inválida');}}if(!confirm('Substituir o preenchimento pelo arquivo?'))return;S={meta:{},a:{},units:{},names:{},notes:{},fields:{},images:{},...s};save();location.reload();}catch(err){alert(err.message);}};
document.getElementById('paper-photo').onchange=async e=>{let file=e.target.files[0];if(!file)return;let image=new Image(),url=URL.createObjectURL(file);try{image.src=url;await image.decode();let scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=image.naturalWidth*scale;canvas.height=image.naturalHeight*scale;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);S.images[paperPhotoField]=canvas.toDataURL('image/jpeg',.85);save();refreshPaper();}finally{URL.revokeObjectURL(url);e.target.value='';}};
