for(let c of Object.values(CFG.itens)){let unit='p'+c.page+'c'+c.col;if(S.units[unit]===undefined)S.units[unit]=Object.keys(CFG.itens).some(k=>CFG.itens[k].page===c.page&&CFG.itens[k].col===c.col&&rows(k).some(r=>r.a));}
